/// <summary>
/// Bug 340986: E2E - Demand - CB201 - Post Provision Batch Job unsuccessful + Full Rebate Value = Write Off
/// </summary>
[
SysOperationJournaledParametersAttribute(true)
]
public class METTAMRebatePostController_Rebate extends TAMRebatePostController
{     
}

Method.Source:
/// <summary>
/// When this is manually created from the batch job journal, we need to default the RebateTransactionType (hidden) to the right value
/// </summary>
/// <returns></returns>
protected container packDataContractInfoObjects()
{
    container ret;

    ret = super();

    ret = METTAMRebateContractHelper::updateRebateTransactionTypeInPackedContract(ret, TAMRebateTransactionType::Rebate);

    return ret;
}

/// <summary>
/// defaultCaption
/// </summary>
/// <returns>defaultCaption</returns>
protected ClassDescription defaultCaption()
{
    return "Post rebate management - Rebate";
}

/// <summary>
///
/// </summary>
/// <param name = "_loadFromSysLastValue"></param>
/// <returns></returns>
public boolean parmLoadFromSysLastValue(boolean _loadFromSysLastValue = loadFromSysLastValue)
{
    return false;
}
